      const pos = clampAccessFloatingPosition(left, top);
      if (!pos) return null;
      els.accessFloatingRoot.style.left = String(pos.left) + "px";
      els.accessFloatingRoot.style.top = String(pos.top) + "px";
      els.accessFloatingRoot.style.right = "auto";
